			/*
			 * 인풋 박스에서 blur 이벤트 발생 시 호출.
			 * 컨트롤이 포커스를 잃은 후 발생하는 이벤트.
			 */
			function onIpb5Blur(/* cpr.events.CFocusEvent */ e){
				/** 
				 * @type cpr.controls.InputBox
				 */
				var ipb5 = e.control;
				
				var email = ipb5.value;
				//alert(email);
				
				// 값을 입력안한경우는 아예 체크를 하지 않는다. 
				if (email == null || email == '' || email == 'undefined') { 
					return;
				} 
				
				// 이메일 유효성 검사 
				if (! email_check(email)) { 
					util.Msg.alert(app, '잘못된 형식의 이메일 주소입니다.'); 
					//$(this).focus(); 
					return false; 
				}

			}

			function email_check( email ) { 
				var regex=/([\w-\.]+)@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.)|(([\w-]+\.)+))([a-zA-Z]{2,4}|[0-9]{1,3})(\]?)$/; 
				return (email != null && email != '' && email != 'undefined' && regex.test(email)); 
			}

